import React, { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Activity,
  ArrowRight,
  BriefcaseBusiness,
  CheckCircle2,
  CircleDollarSign,
  Clock3,
  Loader2,
  MessageCircle,
  Package,
  Plus,
  RefreshCw,
  Search,
  Sparkles,
  Store,
  WandSparkles,
} from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { useSearchParams } from 'react-router-dom';
import { supabase } from '../../lib/supabase';
import { safeLocalStorage } from '../../lib/browserStorage';
import { useListingWizard } from '../../context/ListingWizardContext';
import { MoneyDashboard } from './MoneyDashboard';
import { ManagementDashboard } from './ManagementDashboard';
import { WorkspaceTutorial } from './WorkspaceTutorial';

type WorkspaceActivityKind = 'order' | 'task' | 'product' | 'business' | 'chat';
type SummaryStatus = 'loading' | 'ai' | 'factual';

interface WorkspaceActivityItem {
  id: string;
  kind: WorkspaceActivityKind;
  title: string;
  detail: string;
  occurredAt: string;
  destination: string;
}

interface DashboardStats {
  revenue: number;
  orders: number;
  completedOrders: number;
  newOrders: number;
  unreadMessages: number;
  businesses: number;
  customers: number;
  currency: string;
}

interface DailySummarySnapshot {
  revenue: number;
  currency: string;
  orders: number;
  newOrders: number;
  unreadMessages: number;
  openTasks: number;
  products: number;
  businesses: number;
  recentActivity: Array<{ title: string; detail: string }>;
}

const EMPTY_STATS: DashboardStats = {
  revenue: 0,
  orders: 0,
  completedOrders: 0,
  newOrders: 0,
  unreadMessages: 0,
  businesses: 0,
  customers: 0,
  currency: 'USD',
};

const formatMoney = (amount: unknown, currency = 'USD') => {
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: currency.toUpperCase(),
      maximumFractionDigits: 0,
    }).format(Number(amount) || 0);
  } catch {
    return `${currency.toUpperCase()} ${(Number(amount) || 0).toLocaleString()}`;
  }
};

const buildWorkspaceActivity = ({
  orders,
  tasks,
  products,
  businesses,
  chats,
}: {
  orders: any[];
  tasks: any[];
  products: any[];
  businesses: any[];
  chats: any[];
}): WorkspaceActivityItem[] => {
  const items: WorkspaceActivityItem[] = [
    ...orders.map((order) => ({
      id: `order-${order.id}`,
      kind: 'order' as const,
      title: 'New order received',
      detail: `${String(order.status || 'processing').replaceAll('_', ' ')} · ${formatMoney(order.amount, order.currency || 'USD')}`,
      occurredAt: order.created_at,
      destination: 'money-transactions',
    })),
    ...tasks.map((task) => ({
      id: `task-${task.id}`,
      kind: 'task' as const,
      title: task.status === 'done' ? 'Task completed' : 'Task updated',
      detail: task.title || 'Untitled task',
      occurredAt: task.updated_at || task.created_at,
      destination: 'management-team',
    })),
    ...products.map((product) => ({
      id: `product-${product.id}`,
      kind: 'product' as const,
      title: 'Product published',
      detail: product.title || 'Untitled product',
      occurredAt: product.created_at,
      destination: 'management-products',
    })),
    ...businesses.map((business) => ({
      id: `business-${business.id}`,
      kind: 'business' as const,
      title: 'Business workspace created',
      detail: business.name || 'Untitled business',
      occurredAt: business.created_at,
      destination: 'home',
    })),
    ...chats.map((chat) => ({
      id: `chat-${chat.id}`,
      kind: 'chat' as const,
      title: 'Conversation updated',
      detail: chat.name || chat.last_message || 'Workspace conversation',
      occurredAt: chat.last_message_at || chat.updated_at || chat.created_at,
      destination: 'chats',
    })),
  ];

  return items
    .filter((item) => item.id && item.occurredAt)
    .sort((a, b) => new Date(b.occurredAt).getTime() - new Date(a.occurredAt).getTime())
    .slice(0, 8);
};

const factualSummary = (snapshot: DailySummarySnapshot) => {
  const openTaskText = snapshot.openTasks === 1 ? '1 open task' : `${snapshot.openTasks} open tasks`;
  const messageText = snapshot.unreadMessages === 1 ? '1 unread message' : `${snapshot.unreadMessages} unread messages`;
  const orderText = snapshot.newOrders === 1 ? '1 new order' : `${snapshot.newOrders} new orders`;
  return `Today you have ${messageText}, ${openTaskText}, and ${orderText}. Revenue currently stands at ${formatMoney(snapshot.revenue, snapshot.currency)} across ${snapshot.orders} orders.`;
};

const summaryCacheKey = (userId: string) =>
  `wersee:daily-ai-summary:${userId}:${new Date().toISOString().slice(0, 10)}`;

const readCachedSummary = (userId: string) => {
  const cached = safeLocalStorage.getItem(summaryCacheKey(userId));
  if (!cached) return null;
  try {
    const parsed = JSON.parse(cached) as { text?: unknown };
    return typeof parsed.text === 'string' && parsed.text.trim() ? parsed.text.trim() : null;
  } catch {
    return null;
  }
};

const createDailyAiSummary = async (userId: string, snapshot: DailySummarySnapshot, force = false) => {
  if (!force) {
    const cached = readCachedSummary(userId);
    if (cached) return { text: cached, status: 'ai' as const };
  }

  try {
    const { werseeAi } = await import('../../ai/client');
    const response = await werseeAi.generateText({
      contents: [
        'Write a concise daily workspace summary in English.',
        'Use only the provided facts. Do not invent trends, people, percentages, or advice.',
        'Write 2 short sentences, maximum 55 words. End with one concrete priority for today.',
        `FACTS: ${JSON.stringify(snapshot)}`,
      ].join('\n'),
      config: {
        temperature: 0.2,
        maxOutputTokens: 140,
      },
    });
    const text = response.text.replace(/\s+/g, ' ').trim().slice(0, 520);
    if (!text) throw new Error('EMPTY_AI_SUMMARY');
    safeLocalStorage.setItem(summaryCacheKey(userId), JSON.stringify({
      text,
      generatedAt: new Date().toISOString(),
    }));
    return { text, status: 'ai' as const };
  } catch (error) {
    if (import.meta.env.DEV) console.warn('Daily AI summary unavailable:', error);
    return { text: factualSummary(snapshot), status: 'factual' as const };
  }
};

const activityIcon = (kind: WorkspaceActivityKind) => {
  if (kind === 'order') return CircleDollarSign;
  if (kind === 'task') return CheckCircle2;
  if (kind === 'product') return Package;
  if (kind === 'business') return Store;
  return MessageCircle;
};

const metricCards = (stats: DashboardStats, openTasks: number) => [
  {
    label: 'Revenue',
    value: formatMoney(stats.revenue, stats.currency),
    detail: `${stats.completedOrders} completed`,
    icon: CircleDollarSign,
    color: 'text-emerald-300',
    surface: 'bg-emerald-400/10',
  },
  {
    label: 'Orders',
    value: stats.orders.toLocaleString(),
    detail: `${stats.newOrders} need attention`,
    icon: Package,
    color: 'text-blue-300',
    surface: 'bg-blue-400/10',
  },
  {
    label: 'Messages',
    value: stats.unreadMessages.toLocaleString(),
    detail: 'unread across chats',
    icon: MessageCircle,
    color: 'text-violet-300',
    surface: 'bg-violet-400/10',
  },
  {
    label: 'Tasks',
    value: openTasks.toLocaleString(),
    detail: 'still open',
    icon: CheckCircle2,
    color: 'text-amber-300',
    surface: 'bg-amber-400/10',
  },
];

const sectionTabs = [
  { id: 'overview' as const, label: 'Overview' },
  { id: 'money' as const, label: 'Finance' },
  { id: 'management' as const, label: 'Management' },
];

export const WorkspaceHome = ({ onNavigate }: { onNavigate: (view: string) => void }) => {
  const [searchParams, setSearchParams] = useSearchParams();
  const { openWizard } = useListingWizard();
  const requestedSection = searchParams.get('section');
  const activeTab: 'overview' | 'money' | 'management' = requestedSection === 'finance'
    ? 'money'
    : requestedSection === 'manage'
      ? 'management'
      : 'overview';

  const [recentChats, setRecentChats] = useState<any[]>([]);
  const [tasks, setTasks] = useState<any[]>([]);
  const [businesses, setBusinesses] = useState<any[]>([]);
  const [products, setProducts] = useState<any[]>([]);
  const [workspaceActivity, setWorkspaceActivity] = useState<WorkspaceActivityItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [dashboardError, setDashboardError] = useState('');
  const [userName, setUserName] = useState('');
  const [stats, setStats] = useState<DashboardStats>(EMPTY_STATS);
  const [dailySummary, setDailySummary] = useState('');
  const [summaryStatus, setSummaryStatus] = useState<SummaryStatus>('loading');

  const fetchDashboard = async (forceSummary = false) => {
    setLoading(true);
    setDashboardError('');
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        setDashboardError('Sign in again to load your workspace.');
        return;
      }

      const [
        profileResult,
        chatsResult,
        tasksResult,
        businessesResult,
        recentOrdersResult,
        orderStatsResult,
        productsResult,
        businessCountResult,
      ] = await Promise.all([
        supabase.from('profiles').select('id, full_name, username').eq('id', user.id).maybeSingle(),
        supabase
          .from('chat_participants')
          .select('chat_id, unread_count, chat:chats(id, name, last_message, last_message_at, updated_at, created_at)')
          .eq('user_id', user.id)
          .limit(30),
        supabase.from('tasks').select('id, title, status, priority, created_at, updated_at').eq('user_id', user.id).order('updated_at', { ascending: false }).limit(8),
        supabase.from('businesses').select('id, name, slug, created_at').eq('user_id', user.id).order('created_at', { ascending: false }).limit(6),
        supabase.from('orders').select('id, status, amount, currency, created_at, listing_id').eq('seller_id', user.id).order('created_at', { ascending: false }).limit(8),
        supabase.from('orders').select('amount, buyer_id, listing_id, status, currency').eq('seller_id', user.id),
        supabase.from('listings').select('id, title, price, image_url, images, status, created_at').eq('seller_id', user.id).order('created_at', { ascending: false }).limit(6),
        supabase.from('businesses').select('id', { count: 'exact', head: true }).eq('user_id', user.id),
      ]);

      const profile = profileResult.data;
      setUserName(profile?.full_name || profile?.username || user.email?.split('@')[0] || 'Creator');

      const chats = (chatsResult.data || [])
        .map((participant: any) => {
          const chat = Array.isArray(participant.chat) ? participant.chat[0] : participant.chat;
          return chat ? { ...chat, unread_count: participant.unread_count || 0 } : null;
        })
        .filter(Boolean);
      const uniqueChats = Array.from(new Map(chats.map((chat: any) => [chat.id, chat])).values())
        .sort((left: any, right: any) => {
          const leftDate = left.last_message_at || left.updated_at || left.created_at;
          const rightDate = right.last_message_at || right.updated_at || right.created_at;
          return new Date(rightDate || 0).getTime() - new Date(leftDate || 0).getTime();
        })
        .slice(0, 6);
      const taskRows = tasksResult.data || [];
      const businessRows = businessesResult.data || [];
      const orderRows = orderStatsResult.data || [];
      const recentOrders = recentOrdersResult.data || [];
      const productRows = productsResult.data || [];
      const unreadMessages = (chatsResult.data || []).reduce(
        (total: number, participant: any) => total + (Number(participant.unread_count) || 0),
        0,
      );
      const completedOrders = orderRows.filter((order: any) =>
        !order.status || ['completed', 'paid', 'succeeded', 'success'].includes(String(order.status).toLowerCase()));
      const nextStats: DashboardStats = {
        revenue: completedOrders.reduce((total: number, order: any) => total + (Number(order.amount) || 0), 0),
        orders: orderRows.length,
        completedOrders: completedOrders.length,
        newOrders: orderRows.filter((order: any) => ['pending', 'new'].includes(String(order.status).toLowerCase())).length,
        unreadMessages,
        businesses: businessCountResult.count || businessRows.length,
        customers: new Set(orderRows.map((order: any) => order.buyer_id).filter(Boolean)).size,
        currency: completedOrders.find((order: any) => order.currency)?.currency
          || 'USD',
      };
      const productsWithSales = productRows.map((product: any) => ({
        ...product,
        sales_count: orderRows.filter((order: any) => order.listing_id === product.id).length,
      }));
      const activity = buildWorkspaceActivity({
        orders: recentOrders,
        tasks: taskRows,
        products: productRows,
        businesses: businessRows,
        chats: uniqueChats,
      });
      const failedResults = [
        chatsResult,
        tasksResult,
        businessesResult,
        recentOrdersResult,
        orderStatsResult,
        productsResult,
      ].filter((result) => result.error);

      setRecentChats(uniqueChats);
      setTasks(taskRows);
      setBusinesses(businessRows);
      setProducts(productsWithSales);
      setWorkspaceActivity(activity);
      setStats(nextStats);
      if (failedResults.length) {
        setDashboardError(failedResults.length === 6
          ? 'Your workspace data is temporarily unavailable.'
          : 'Some workspace data could not be loaded.');
      }

      setSummaryStatus('loading');
      const summary = await createDailyAiSummary(user.id, {
        revenue: nextStats.revenue,
        currency: nextStats.currency,
        orders: nextStats.orders,
        newOrders: nextStats.newOrders,
        unreadMessages: nextStats.unreadMessages,
        openTasks: taskRows.filter((task: any) => task.status !== 'done').length,
        products: productRows.length,
        businesses: nextStats.businesses,
        recentActivity: activity.slice(0, 4).map(({ title, detail }) => ({ title, detail })),
      }, forceSummary);
      setDailySummary(summary.text);
      setSummaryStatus(summary.status);
    } catch (error) {
      console.error('Error loading workspace dashboard:', error);
      setDashboardError('Your workspace data is temporarily unavailable.');
      setSummaryStatus('factual');
      setDailySummary('Your daily summary is unavailable until workspace data reconnects.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void fetchDashboard();
  }, []);

  const selectWorkspaceTab = (tab: 'overview' | 'money' | 'management') => {
    const nextParams = new URLSearchParams(searchParams);
    if (tab === 'overview') nextParams.delete('section');
    else nextParams.set('section', tab === 'money' ? 'finance' : 'manage');
    setSearchParams(nextParams, { replace: false });
  };

  const openTasks = tasks.filter((task) => task.status !== 'done');
  const cards = metricCards(stats, openTasks.length);
  const greeting = new Date().getHours() < 12 ? 'Good morning' : new Date().getHours() < 18 ? 'Good afternoon' : 'Good evening';
  const tabMotion = {
    initial: { opacity: 0, y: 8 },
    animate: { opacity: 1, y: 0, transition: { duration: 0.25 } },
    exit: { opacity: 0, y: -8, transition: { duration: 0.16 } },
  };

  return (
    <div className="mx-auto flex min-h-full w-full max-w-[1600px] flex-col gap-3 lg:h-full lg:min-h-0">
      <div className="workspace-home-section-tabs flex shrink-0 items-center justify-between">
        <div role="tablist" aria-label="Workspace sections" className="flex items-center gap-1 rounded-2xl border border-white/5 bg-white/[0.035] p-1">
          {sectionTabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={activeTab === tab.id}
              onClick={() => selectWorkspaceTab(tab.id)}
              className={`rounded-xl px-4 py-2 text-xs font-bold transition-colors ${
                activeTab === tab.id ? 'bg-white text-black' : 'text-white/45 hover:bg-white/5 hover:text-white'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'overview' ? (
          <motion.section
            key="overview"
            {...tabMotion}
            className="flex flex-col gap-3 lg:min-h-0 lg:flex-1 lg:overflow-hidden"
            aria-label="Workspace overview"
          >
            <div className="flex shrink-0 items-center justify-between gap-4 rounded-[1.6rem] border border-white/[0.07] bg-gradient-to-r from-white/[0.055] to-white/[0.02] px-5 py-4">
              <div className="min-w-0">
                <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-violet-300">
                  <Sparkles className="h-3.5 w-3.5" />
                  Today at Wersee
                </div>
                <h1 className="mt-1 truncate text-xl font-black tracking-tight text-white md:text-2xl">
                  {greeting}, {userName || 'Creator'}
                </h1>
              </div>
              <div className="flex shrink-0 items-center gap-2">
                <button
                  type="button"
                  onClick={() => onNavigate('search-results')}
                  className="hidden h-10 items-center gap-2 rounded-xl border border-white/10 px-3 text-xs font-semibold text-white/60 transition-colors hover:bg-white/5 hover:text-white sm:flex"
                >
                  <Search className="h-4 w-4" />
                  Search
                </button>
                <button
                  type="button"
                  onClick={() => openWizard('product')}
                  className="flex h-10 items-center gap-2 rounded-xl bg-white px-4 text-xs font-black text-black transition-transform hover:scale-[1.02] active:scale-95"
                >
                  <Plus className="h-4 w-4" />
                  Create
                </button>
              </div>
            </div>

            {dashboardError ? (
              <div className="flex shrink-0 items-center justify-between gap-3 rounded-xl border border-amber-400/15 bg-amber-400/[0.06] px-4 py-2.5 text-xs text-amber-100/70">
                <span>{dashboardError}</span>
                <button type="button" onClick={() => void fetchDashboard()} className="font-bold text-white">Retry</button>
              </div>
            ) : null}

            <div className="grid shrink-0 grid-cols-2 gap-2 lg:grid-cols-4">
              {cards.map((card) => {
                const Icon = card.icon;
                return (
                  <div key={card.label} className="flex min-w-0 items-center gap-3 rounded-[1.35rem] border border-white/[0.07] bg-[#121214] px-3.5 py-3">
                    <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${card.surface} ${card.color}`}>
                      <Icon className="h-4 w-4" />
                    </span>
                    <span className="min-w-0">
                      <span className="block text-[10px] font-bold uppercase tracking-[0.12em] text-white/35">{card.label}</span>
                      {loading ? <span className="mt-1 block h-5 w-16 animate-pulse rounded bg-white/10" /> : (
                        <span className="block truncate text-lg font-black tracking-tight text-white">{card.value}</span>
                      )}
                      <span className="hidden truncate text-[10px] text-white/35 xl:block">{card.detail}</span>
                    </span>
                  </div>
                );
              })}
            </div>

            <div className="grid gap-3 lg:min-h-0 lg:flex-1 lg:grid-cols-12 lg:grid-rows-2">
              <article className="relative overflow-hidden rounded-[1.55rem] border border-violet-400/15 bg-gradient-to-br from-violet-500/[0.14] via-[#15131b] to-[#101012] p-4 lg:col-span-5">
                <div className="absolute -right-12 -top-16 h-44 w-44 rounded-full bg-violet-500/15 blur-3xl" />
                <div className="relative flex h-full min-h-0 flex-col">
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2">
                      <span className="flex h-8 w-8 items-center justify-center rounded-xl bg-violet-400/15 text-violet-200">
                        <WandSparkles className="h-4 w-4" />
                      </span>
                      <div>
                        <h2 className="text-sm font-black text-white">Daily AI summary</h2>
                        <p className="text-[10px] text-white/35">Built from today&apos;s workspace data</p>
                      </div>
                    </div>
                    <span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase tracking-wider ${
                      summaryStatus === 'ai' ? 'bg-emerald-400/10 text-emerald-300' : 'bg-amber-400/10 text-amber-200'
                    }`}>
                      {summaryStatus === 'loading' ? 'Thinking' : summaryStatus === 'ai' ? 'AI ready' : 'Factual view'}
                    </span>
                  </div>
                  <div className="flex min-h-0 flex-1 items-center">
                    {summaryStatus === 'loading' ? (
                      <div className="flex items-center gap-2 text-sm text-white/45">
                        <Loader2 className="h-4 w-4 animate-spin" />
                        Preparing your daily brief…
                      </div>
                    ) : (
                      <p className="line-clamp-4 text-sm font-medium leading-6 text-white/80">{dailySummary}</p>
                    )}
                  </div>
                  <div className="flex items-center justify-between">
                    <button type="button" onClick={() => window.dispatchEvent(new CustomEvent('open-ai-sidebar'))} className="text-[11px] font-bold text-violet-200 hover:text-white">
                      Ask Wersee AI <ArrowRight className="ml-1 inline h-3.5 w-3.5" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void fetchDashboard(true)}
                      disabled={summaryStatus === 'loading'}
                      className="rounded-lg p-2 text-white/35 transition-colors hover:bg-white/5 hover:text-white disabled:opacity-40"
                      aria-label="Refresh daily summary"
                    >
                      <RefreshCw className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              </article>

              <article className="flex min-h-[190px] flex-col overflow-hidden rounded-[1.55rem] border border-white/[0.07] bg-[#121214] p-4 lg:col-span-4 lg:min-h-0">
                <div className="mb-2 flex items-center justify-between">
                  <div>
                    <h2 className="text-sm font-black text-white">Messages</h2>
                    <p className="text-[10px] text-white/35">{stats.unreadMessages} unread</p>
                  </div>
                  <button type="button" onClick={() => onNavigate('chats')} className="text-[10px] font-bold text-white/40 hover:text-white">View all</button>
                </div>
                <div className="min-h-0 flex-1 space-y-1 overflow-hidden">
                  {loading ? (
                    <div className="flex h-full items-center justify-center"><Loader2 className="h-4 w-4 animate-spin text-white/30" /></div>
                  ) : recentChats.length ? recentChats.slice(0, 3).map((chat) => (
                    <button key={chat.id} type="button" onClick={() => onNavigate('chats')} className="flex w-full items-center gap-2.5 rounded-xl px-2 py-2 text-left transition-colors hover:bg-white/[0.04]">
                      <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-violet-400/20 to-blue-400/10 text-violet-200">
                        <MessageCircle className="h-3.5 w-3.5" />
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-xs font-bold text-white">{chat.name || 'Workspace chat'}</span>
                        <span className="block truncate text-[10px] text-white/35">{chat.last_message || 'Open conversation'}</span>
                      </span>
                      {chat.unread_count ? <span className="min-w-5 rounded-full bg-violet-500 px-1.5 py-0.5 text-center text-[9px] font-black text-white">{chat.unread_count}</span> : null}
                    </button>
                  )) : (
                    <div className="flex h-full flex-col items-center justify-center text-center">
                      <MessageCircle className="h-5 w-5 text-white/20" />
                      <p className="mt-2 text-xs text-white/35">No conversations yet</p>
                    </div>
                  )}
                </div>
              </article>

              <article className="flex min-h-[190px] flex-col overflow-hidden rounded-[1.55rem] border border-white/[0.07] bg-[#121214] p-4 lg:col-span-3 lg:min-h-0">
                <div className="mb-2">
                  <h2 className="text-sm font-black text-white">Quick actions</h2>
                  <p className="text-[10px] text-white/35">Keep moving</p>
                </div>
                <div className="grid min-h-0 flex-1 grid-cols-2 gap-2">
                  {[
                    { label: 'Product', icon: Package, action: () => openWizard('product') },
                    { label: 'Business', icon: BriefcaseBusiness, action: () => onNavigate('create-business') },
                    { label: 'Finance', icon: CircleDollarSign, action: () => onNavigate('money-balance') },
                    { label: 'Storage', icon: Store, action: () => onNavigate('storage') },
                  ].map((action) => {
                    const Icon = action.icon;
                    return (
                      <button key={action.label} type="button" onClick={action.action} className="flex min-h-0 flex-col items-start justify-center rounded-xl border border-white/[0.06] bg-white/[0.025] px-3 text-left transition-colors hover:bg-white/[0.06]">
                        <Icon className="mb-1.5 h-4 w-4 text-white/55" />
                        <span className="text-[11px] font-bold text-white">{action.label}</span>
                      </button>
                    );
                  })}
                </div>
              </article>

              <article className="flex min-h-[210px] flex-col overflow-hidden rounded-[1.55rem] border border-white/[0.07] bg-[#121214] p-4 lg:col-span-5 lg:min-h-0">
                <div className="mb-2 flex items-center justify-between">
                  <div>
                    <h2 className="text-sm font-black text-white">Recent activity</h2>
                    <p className="text-[10px] text-white/35">Across your workspace</p>
                  </div>
                  <Activity className="h-4 w-4 text-white/25" />
                </div>
                <div className="min-h-0 flex-1 space-y-1 overflow-hidden">
                  {workspaceActivity.length ? workspaceActivity.slice(0, 4).map((item) => {
                    const Icon = activityIcon(item.kind);
                    return (
                      <button key={item.id} type="button" onClick={() => onNavigate(item.destination)} className="flex w-full items-center gap-2.5 rounded-xl px-2 py-1.5 text-left transition-colors hover:bg-white/[0.04]">
                        <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-white/[0.05] text-white/45"><Icon className="h-3.5 w-3.5" /></span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[11px] font-bold text-white">{item.title}</span>
                          <span className="block truncate text-[10px] text-white/30">{item.detail}</span>
                        </span>
                        <span className="shrink-0 text-[9px] text-white/25">{formatDistanceToNow(new Date(item.occurredAt), { addSuffix: true })}</span>
                      </button>
                    );
                  }) : (
                    <div className="flex h-full items-center justify-center text-xs text-white/35">New workspace activity will appear here.</div>
                  )}
                </div>
              </article>

              <article className="flex min-h-[210px] flex-col overflow-hidden rounded-[1.55rem] border border-white/[0.07] bg-[#121214] p-4 lg:col-span-4 lg:min-h-0">
                <div className="mb-2 flex items-center justify-between">
                  <div>
                    <h2 className="text-sm font-black text-white">Today&apos;s tasks</h2>
                    <p className="text-[10px] text-white/35">{openTasks.length} open</p>
                  </div>
                  <button type="button" onClick={() => onNavigate('management-team')} className="text-[10px] font-bold text-white/40 hover:text-white">Manage</button>
                </div>
                <div className="min-h-0 flex-1 space-y-1 overflow-hidden">
                  {openTasks.length ? openTasks.slice(0, 4).map((task) => (
                    <button key={task.id} type="button" onClick={() => onNavigate('management-team')} className="flex w-full items-center gap-2.5 rounded-xl px-2 py-2 text-left transition-colors hover:bg-white/[0.04]">
                      <span className={`h-2 w-2 shrink-0 rounded-full ${
                        task.priority === 'high' ? 'bg-rose-400' : task.priority === 'medium' ? 'bg-amber-300' : 'bg-blue-300'
                      }`} />
                      <span className="min-w-0 flex-1 truncate text-[11px] font-semibold text-white/80">{task.title || 'Untitled task'}</span>
                      <Clock3 className="h-3.5 w-3.5 shrink-0 text-white/20" />
                    </button>
                  )) : (
                    <div className="flex h-full flex-col items-center justify-center text-center">
                      <CheckCircle2 className="h-5 w-5 text-emerald-300/60" />
                      <p className="mt-2 text-xs text-white/35">Nothing open right now</p>
                    </div>
                  )}
                </div>
              </article>

              <article className="flex min-h-[210px] flex-col overflow-hidden rounded-[1.55rem] border border-white/[0.07] bg-[#121214] p-4 lg:col-span-3 lg:min-h-0">
                <div className="mb-2 flex items-center justify-between">
                  <div>
                    <h2 className="text-sm font-black text-white">Products</h2>
                    <p className="text-[10px] text-white/35">{products.length} recent</p>
                  </div>
                  <button type="button" onClick={() => onNavigate('management-products')} className="text-[10px] font-bold text-white/40 hover:text-white">View all</button>
                </div>
                <div className="min-h-0 flex-1 space-y-1 overflow-hidden">
                  {products.length ? products.slice(0, 3).map((product) => {
                    const image = product.image_url || product.images?.[0];
                    return (
                      <button key={product.id} type="button" onClick={() => onNavigate('management-products')} className="flex w-full items-center gap-2.5 rounded-xl px-1.5 py-2 text-left transition-colors hover:bg-white/[0.04]">
                        <span className="flex h-8 w-8 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-white/[0.05] text-white/25">
                          {image ? <img src={image} alt="" className="h-full w-full object-cover" /> : <Package className="h-3.5 w-3.5" />}
                        </span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[11px] font-bold text-white">{product.title || 'Untitled product'}</span>
                          <span className="block text-[9px] text-white/30">{product.sales_count || 0} sales</span>
                        </span>
                      </button>
                    );
                  }) : (
                    <button type="button" onClick={() => openWizard('product')} className="flex h-full w-full flex-col items-center justify-center rounded-xl border border-dashed border-white/10 text-xs text-white/35 hover:text-white">
                      <Plus className="mb-2 h-4 w-4" />
                      Add your first product
                    </button>
                  )}
                </div>
              </article>
            </div>

            <div className="flex shrink-0 items-center justify-between px-1 text-[10px] text-white/25 lg:hidden">
              <span>{businesses.length} businesses · {stats.customers} customers</span>
              <span>Live workspace data</span>
            </div>
          </motion.section>
        ) : activeTab === 'money' ? (
          <motion.section key="money" {...tabMotion} className="min-h-0 flex-1" aria-label="Finance">
            <MoneyDashboard />
          </motion.section>
        ) : (
          <motion.section key="management" {...tabMotion} className="min-h-0 flex-1" aria-label="Management">
            <ManagementDashboard onNavigate={onNavigate} />
          </motion.section>
        )}
      </AnimatePresence>

      <WorkspaceTutorial />
    </div>
  );
};
