import { safeLocalStorage } from './browserStorage';

export type WorkspaceTopbarTone = 'white' | 'dark' | 'indigo' | 'violet' | 'emerald';

export const WORKSPACE_TOPBAR_TONE_STORAGE_KEY = 'wersee:workspace-topbar-tone';
export const WORKSPACE_TOPBAR_TONE_EVENT = 'wersee:workspace-topbar-tone-change';

export const isWorkspaceTopbarTone = (value: unknown): value is WorkspaceTopbarTone =>
  value === 'white'
  || value === 'dark'
  || value === 'indigo'
  || value === 'violet'
  || value === 'emerald';

export const getWorkspaceTopbarTonePreference = (): WorkspaceTopbarTone => {
  const stored = safeLocalStorage.getItem(WORKSPACE_TOPBAR_TONE_STORAGE_KEY);
  return isWorkspaceTopbarTone(stored) ? stored : 'dark';
};

export const setWorkspaceTopbarTonePreference = (tone: WorkspaceTopbarTone) => {
  safeLocalStorage.setItem(WORKSPACE_TOPBAR_TONE_STORAGE_KEY, tone);
  window.dispatchEvent(new CustomEvent<WorkspaceTopbarTone>(WORKSPACE_TOPBAR_TONE_EVENT, {
    detail: tone,
  }));
};
